import {showAssessmentReview} from '../assessment-feedback.mjs';
import {VERSION,STORAGE_KEY,STEPS,DATA,A,B,mean,sampleSD,wealth,experiment,DEFAULT_PARAMETER,PRACTICE,ASSESSMENTS,check,grade,freshState,restoreState,invalidate,labEvidence} from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
const CONFIG={title:'Combine, then question.',lead:'A portfolio is a set of exposures and a policy. Compare weighted returns, drift, resetting and benchmark sensitivity without turning a short sample into a recommendation.',outcomes:'CH6-01: aligned weighted returns; CH6-02: allocation concentration and diversification; CH6-03: constant-mix versus buy-and-hold; CH6-04: beta and correlation.',labTitle:'One allocation, two policies.',labLead:'Change only the initial A weight. Compare constant-mix rebalancing, buy-and-hold drift and sample benchmark sensitivity.',parameter:'Starting/target A allocation (%), 0–100; B gets the remainder',labIntro:'Start with hypothetical wealth 100. Constant mix resets to the target at every month boundary, before the next month’s return. Buy-and-hold keeps asset units unchanged so sleeve values and weights drift. Both use the same supplied dates and total returns. No external flows, costs, taxes, slippage or constraints are modelled. A reset can require trades; omitted costs can change the comparison. No randomness or seed is used.',prediction:'Predict how moving A from 50% to 80% changes first-month return, concentration and the two wealth paths. Explain why.',handLabel:'Latest run: first monthly constant-mix portfolio return (%)',handHint:'Use starting fractions: wA×10 + (1−wA)×(−5). This check uses the latest A allocation.',reflection:'Compare two allocations and both policies. Explain weight drift, sample diversification/beta and omitted trading costs (50+ characters).',criteria:'I compared allocations and policies, checked the first weighted return, and rejected a universal or net-performance winner.',comparison:'Compare A 50% and A 80%, keeping dates and data fixed. Re-run A 50% to confirm reproducibility.',card:'portfolio',next:'../chapter-07/',nextLabel:'Chapter 7 →'};
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=freshState(),storageOK=true,page='start';try{state=restoreState(localStorage.getItem(STORAGE_KEY));}catch{storageOK=false;}
const value=id=>state.fields[id]||'',fmt=n=>n===null?'Undefined':Number(n).toFixed(3),field=(id,label,area=false,defaultValue='')=>`<label class="field" for="${id}">${label}</label>${area?`<textarea id="${id}" data-save>${esc(state.fields[id]??defaultValue)}</textarea>`:`<input id="${id}" data-save type="number" step="any" value="${esc(state.fields[id]??defaultValue)}">`}`,box=(id,label)=>`<label class="option"><input id="${id}" type="checkbox" data-save ${value(id)==='yes'?'checked':''}><span>${label}</span></label>`;
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'Saved on this device':'Saving unavailable · export before leaving';nav();}
function nav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#progress-label').textContent=`${n} of 8 steps complete`;$('#progress-percent').textContent=Math.round(n/8*100)+'%';$('#progress').value=n;$('#navigation').innerHTML=STEPS.map(([id,t,m],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':i+1}</span><span>${t}<small>${m} min${state.done[id]?' · complete':''}</small></span></a>`).join('');}
function feedback(id,text,error=false){const el=$('#'+id);el.textContent=text;el.className='feedback'+(error?' error':'');el.tabIndex=-1;el.focus();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const table=()=>`<div class="table-wrap"><table><caption>Original hypothetical monthly total returns, percentage units. Six aligned months; no fees, taxes or flows.</caption><thead><tr><th scope="col">Month</th><th scope="col">Asset A (%)</th><th scope="col">Asset B (%)</th><th scope="col">Benchmark (%)</th></tr></thead><tbody>${DATA.map(r=>`<tr><th scope="row">${r.date}</th><td>${r.a}</td><td>${r.b}</td><td>${r.market}</td></tr>`).join('')}</tbody></table></div><p><a href="returns.csv" download>Download the six-month CSV</a></p>`;
const header=(title,lead)=>`<div class="eyebrow">Chapter 06 · ${STEPS.find(s=>s[0]===page)?.[2]} minutes</div><h1>${title}</h1><p class="lead">${lead}</p>`;
function start(){return header(CONFIG.title,CONFIG.lead)+`<div class="pill-row"><span class="pill">180-minute core</span><span class="pill">No installation</span><span class="pill">Optional Python +35 min</span></div><section class="panel"><h2>Your independent learning setup</h2><p>This chapter stands alone. Bring paper and a calculator with square-root and power keys. Work through each explanation, example, guided check and new case. There is no instructor dependency or countdown. Return values use percentage units (2 means 2%, not .02); weights use fractions. Explain answers in your own words and revise after feedback.</p><ol><li>Read the <a href="data-dictionary.md">data dictionary</a>, download the CSV below and confirm same-date pairs.</li><li>Use <a href="guide.html">the complete text/paper route</a> if you prefer a printed path, without JavaScript or installation.</li><li>Local progress keeps all numerical practice attempts, lab runs and independent attempts. Export is a record, not an import or cross-device sync.</li></ol>${box('setup','I can find the data, calculator, hints, text route, Export and Privacy & reset.')}<button data-action="setup">Confirm setup & continue →</button><div id="feedback-start" class="feedback" role="status"></div></section><section class="panel"><h2>Outcomes and evidence</h2><p>${CONFIG.outcomes}</p><p>Complete both checked tasks and a self-reviewed explanation in each lesson; make two lab runs with a changed input and a hand check; meet the independent transfer criteria and respond to feedback; finish a method/check/limit card. Numerical checks do not grade prose quality.</p>${table()}<p>These are original hypothetical teaching data, not historical market performance. Total returns include distributions; fees, taxes, transaction costs and flows are omitted. Six months cannot establish a durable market relationship or an investment recommendation. Core and extension timing is proposed, not learner validated.</p></section>`;}
function practice(step){const l=LESSONS[step];return header(l.title,l.objective)+l.body+table()+`<section class="panel"><h2>Try, check, explain, revise</h2><p>Use a calculator. Enter numbers only: no % sign. Round to two decimals or keep more precision. Choice questions use the stated number.</p>${PRACTICE[step].map((q,i)=>`<div class="practice-item">${field(q.id,q.title)}<div class="actions"><button data-action="practice" data-id="${q.id}">Check task ${i+1}</button><details><summary>Hint</summary><p>${q.hint}</p></details></div><div id="feedback-${q.id}" class="feedback" role="status">${state.checked[q.id]?'Correct. '+q.hint:''}</div></div>`).join('')}<h3>Explain and revise</h3><p>${l.reflection}</p>${field(step+'Reflection','My explanation, check or correction',true)}${box(step+'Criteria',l.criteria)}<p class="mini">Self-review checks reasoning; the app checks numerical answers and that you supplied at least 30 characters. Prose quality is not automatically graded.</p><button data-action="save-step">Save this lesson</button><div id="feedback-step" class="feedback" role="status">${state.done[step]?'Lesson evidence saved.':''}</div></section>`;}
function pathChart(left,right,leftLabel,rightLabel){const all=[...left,...right],lo=Math.min(...all)-2,hi=Math.max(...all)+2,x=i=>45+i*75,y=v=>185-(v-lo)/(hi-lo)*140,points=a=>a.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg class="growth-chart" viewBox="0 0 560 235" role="img" aria-label="Wealth paths from initial100. Solid: ${leftLabel}; dashed: ${rightLabel}. All exact values follow in the table."><path d="M40 25V190H520" stroke="#607265" fill="none"/><polyline class="chart-line" points="${points(left)}"/><polyline class="chart-alt" points="${points(right)}"/><text x="45" y="215">Initial → six monthly observations</text><text x="45" y="20">Wealth (currency units)</text></svg><p>Solid line: ${leftLabel}. Dashed brown: ${rightLabel}. The exact numeric table provides the same evidence.</p>`;}
function runResult(run){return `<h3>A target ${fmt(run.parameter)}%; B ${fmt(100-run.parameter)}%</h3><p>Allocation concentration H=${fmt((run.parameter/100)**2+(1-run.parameter/100)**2)}; constant-mix monthly sample SD ${fmt(run.sd)} percentage points; correlation with benchmark ${fmt(run.correlation)}; sample beta ${fmt(run.beta)}. Undefined means a zero denominator, not zero exposure.</p>${pathChart(run.rows.map(r=>r.mix),run.rows.map(r=>r.buyHold),'Constant mix','Buy-and-hold')}<div class="table-wrap"><table><caption>Exact policy values. A weight is the buy-and-hold fraction after the completed month; constant mix resets to the target before the next month. First-month return is the hand-check target.</caption><thead><tr><th scope="col">Month</th><th scope="col">Constant mix wealth</th><th scope="col">Buy-and-hold wealth</th><th scope="col">Drifted A weight</th><th scope="col">Mix return (%)</th></tr></thead><tbody>${run.rows.map(r=>`<tr><th scope="row">${r.date}</th><td>${fmt(r.mix)}</td><td>${fmt(r.buyHold)}</td><td>${fmt(r.weightA)}</td><td>${fmt(r.mixReturn)}</td></tr>`).join('')}</tbody></table></div>${scatter(run)}</p>`;}
function scatter(run){const pairs=DATA.map((r,i)=>({date:r.date,x:r.market,y:run.rows[i+1].mixReturn})),x=v=>70+(v+4)*55,y=v=>210-(v+10)*10;return `<h3>Benchmark sensitivity: same-date pairs</h3><svg class="scatter" viewBox="0 0 560 260" role="img" aria-label="Scatter plot: benchmark return horizontally, constant-mix portfolio return vertically. Exact pairs follow."><path d="M60 20V225H520" stroke="#607265" fill="none"/><text x="100" y="250">Benchmark monthly return (%)</text><text x="70" y="18">Portfolio monthly return (%)</text>${pairs.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="5"/>`).join('')}</svg><table><caption>Scatter values, same-month total returns in percentage units. Beta is a sample regression slope with intercept; no next-period outcome is guaranteed.</caption><thead><tr><th scope="col">Month</th><th scope="col">Benchmark x (%)</th><th scope="col">Portfolio y (%)</th></tr></thead><tbody>${pairs.map(p=>`<tr><th scope="row">${p.date}</th><td>${p.x}</td><td>${fmt(p.y)}</td></tr>`).join('')}</tbody></table>`;}
function lab(){const r=state.runs.at(-1);return header(CONFIG.labTitle,CONFIG.labLead)+`<p>${CONFIG.labIntro}</p><section class="panel"><h2>1. Predict and run</h2>${field('prediction',CONFIG.prediction,true)}${field('parameter',CONFIG.parameter,false,String(DEFAULT_PARAMETER))}<div class="actions"><button data-action="run">Run comparison</button><button data-action="parameter-default" class="secondary">Restore default input</button></div><div id="feedback-run" class="feedback" role="status"></div>${r?runResult(r):'<p>Your chart and complete numeric table appear after the first run.</p>'}</section><section class="panel"><h2>2. Hand-check, change, explain</h2><p>${CONFIG.comparison} Each run retains its inputs and prediction; earlier attempts remain in the log.</p>${field('hand',CONFIG.handLabel)}<button data-action="hand">Check my hand calculation</button><div id="feedback-hand" class="feedback" role="status">${value('handVerified')==='yes'?'Latest run hand check verified.':''}</div>${field('labReflection',CONFIG.reflection,true)}${box('labCriteria',CONFIG.criteria)}<details><summary>Review and revise</summary><p>${CONFIG.handHint} Your comparison must name the input changed, a checked numeric result, what the policy or metric means, and at least one material omitted assumption. A favourable investment result is not required. Explain a mistake or verification and revise unsupported claims.</p></details><div class="actions"><button data-action="save-lab">Save lab evidence</button><button data-action="csv" class="secondary">Export every run (CSV)</button></div><div id="feedback-lab" class="feedback" role="status">${state.done.lab?'Lab evidence saved.':''}</div></section><section class="panel"><h2>All runs retained (${state.runs.length})</h2><ol>${state.runs.map((r,i)=>`<li>Run ${i+1}; input ${r.parameter}; ${esc(r.time)}; prediction: ${esc(r.prediction)}</li>`).join('')||'<li>No runs yet.</li>'}</ol><p>Restoring the default input retains the log. Privacy & reset deletes this chapter’s browser record.</p></section>`;}
function assessment(){const a=state.attempts.at(-1);return header('Use a fresh case.','Independent transfer · Attempt all eight questions before checking. Then act on the feedback and resubmit if needed.')+`<section class="panel"><p>No countdown. Calculator and paper allowed. Work independently before revealing feedback. Pass: at least 7 of 8, including all critical questions labelled below. This is formative self-learning, not a secure exam or credential.</p>${ASSESSMENTS.map(q=>field('quiz-'+q.id,q.title+(q.critical?' <span class="critical-label">Critical question</span>':''))).join('')}<button data-action="grade">Check independent attempt</button><div id="feedback-assessment" class="feedback" role="status">${a?`${a.score}/8 on last submitted attempt. ${a.passed?'Numerical and critical criteria met.':'Revise and submit again.'} ${value('quizDirty')==='yes'?'Answers or response have changed: resubmit current answers.':''}`:''}</div><details><summary>Previous attempt log (${state.attempts.length})</summary><ol>${state.attempts.map(a=>`<li>${esc(a.time)}: ${a.score}/8; ${a.passed?'criteria met':'revisit'}${a.revision?' · response saved':''}</li>`).join('')}</ol></details><h2>Respond to feedback</h2>${field('revision','Describe one specific correction or verification and its reason (at least 30 characters).',true)}<button data-action="revision">Save feedback response</button><div id="feedback-revision" class="feedback" role="status">${state.done.assessment?'Independent evidence and response saved.':''}</div></section>`;}
function finish(){return header('Keep a portfolio comparison card.','Explain the convention, a checked result and the limit of the evidence. Save a tool for the next chapter.')+`<section class="panel">${field('cardMethod','My convention: frequency, weighting, policy, peak or denominator convention (30+ characters).',true)}${field('cardCheck','My checked number, units and a hand calculation (30+ characters).',true)}${field('cardLimit','My sample limitation, omitted cost or next evidence check (30+ characters).',true)}${box('cardCriteria','I checked my arithmetic and described a meaningful limitation, rather than a forecast.')}<p>The app checks completion, not the substantive quality of prose. Compare your card with the criteria below.</p><details><summary>Card self-review rubric</summary><p>Method: explicit convention and inputs. Check: reproducible number with correct units. Limit: what the tiny sample cannot justify and what more evidence would be needed. Revise claims of guaranteed future returns, universal policy winners or complete risk measurement.</p></details><button data-action="card">Save my portfolio comparison card</button><div id="feedback-finish" class="feedback" role="status"></div><h2>Evidence checklist</h2><ul>${STEPS.map(([id,t])=>`<li>${state.done[id]?'Complete':'To do'}: ${t}</li>`).join('')}</ul><button data-action="export" class="secondary">Export my complete chapter record</button></section><section class="panel"><h2>Sources and next steps</h2><ul>${SOURCES.map(([t,u])=>`<li><a href="${u}">${t}</a></li>`).join('')}</ul><p>Primary sources checked 31 October 2026. All numerical data and worked tasks are original hypothetical teaching material. Core pacing is proposed, not learner validated. Full screen-reader testing and a human learning pilot remain pending.</p><p><a href="../python/?chapter=6#ch6-weights">Optional: consolidate in Python (+35 minutes)</a>. Two scripts consolidate this chapter’s calculations; separate Python progress and setup time. This is beyond the 30-hour noncoding core.</p></section>`;}
function render(focus=true){const next=location.hash.slice(1)||'start';if(next==='lesson'&&$('#lesson').children.length){$('#lesson').focus();return;}page=next;if(!STEPS.some(s=>s[0]===page))page='start';const i=STEPS.findIndex(s=>s[0]===page);$('#lesson').innerHTML=(LESSONS[page]?practice(page):({start,lab,assessment,finish}[page])())+`<div class="bottom-nav">${i?`<a href="#${STEPS[i-1][0]}">← Previous step</a>`:'<a href="../chapter-05/">← Chapter 5</a>'}${i<7?`<a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]}</a>`:`<a href="${CONFIG.next}">${CONFIG.nextLabel}</a>`}</div>`;nav();if(page==='assessment'&&state.attempts.length){const a=state.attempts.at(-1);showAssessmentReview($('#feedback-assessment'),ASSESSMENTS,a.answers,a,check,false,ASSESSMENTS.some(q=>String(a.answers[q.id])!==value('quiz-'+q.id)));}if(focus)$('#lesson').focus();}
document.addEventListener('input',e=>{if(!e.target.matches('[data-save]'))return;const id=e.target.id;state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;invalidate(state,id);persist();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='export'){download('qf-chapter-06-record.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2));$('#announcement').textContent='Chapter 6 record exported.';}
if(action==='setup'){if(value('setup')!=='yes')return feedback('feedback-start','Confirm the setup checklist first.',true);state.done.start=true;persist();location.hash='weights';}
if(action==='practice'){const q=Object.values(PRACTICE).flat().find(q=>q.id===e.target.dataset.id),ok=check(q,value(q.id));state.checked[q.id]=ok;state.practiceAttempts.push({id:q.id,raw:value(q.id),correct:ok,time:new Date().toISOString()});delete state.done[page];persist();feedback('feedback-'+q.id,ok?'Correct. '+q.hint:'Revisit. '+q.hint+' Use the stated units, revise, and check again.',!ok);}
if(action==='save-step'){if(!PRACTICE[page].every(q=>state.checked[q.id]&&check(q,value(q.id)))||value(page+'Reflection').trim().length<30||value(page+'Criteria')!=='yes')return feedback('feedback-step','Check both tasks correctly, write a specific explanation (30+ characters), and confirm your self-review.',true);state.done[page]=true;persist();feedback('feedback-step','Lesson evidence saved. Your prose is self-reviewed against the stated criteria.');}
if(action==='parameter-default'){state.fields.parameter=String(DEFAULT_PARAMETER);delete state.done.lab;persist();render();}
if(action==='run'){if(value('prediction').trim().length<20)return feedback('feedback-run','Write a prediction with a reason (20+ characters) before running.',true);if(state.fields.parameter!==undefined&&state.fields.parameter.trim()==='')return feedback('feedback-run','Enter a numeric input or restore the default before running.',true);try{const result=experiment(Number(state.fields.parameter??DEFAULT_PARAMETER));state.runs.push({...result,prediction:value('prediction'),time:new Date().toISOString()});state.fields.hand='';state.fields.handVerified='';delete state.done.lab;persist();render(false);feedback('feedback-run','Run retained. Read the exact table, hand-check, change the input and rerun.');}catch(err){feedback('feedback-run',err.message,true);}}
if(action==='hand'){const r=state.runs.at(-1),ok=r&&check({answer:r.hand,tolerance:.011},value('hand'));state.fields.handVerified=ok?'yes':'';delete state.done.lab;persist();feedback('feedback-hand',ok?'Correct. Latest run hand calculation verified.':CONFIG.handHint+' Revise and check again.',!ok);}
if(action==='save-lab'){if(!labEvidence(state))return feedback('feedback-lab','Run two distinct input values with current input and prediction matching the latest run, verify its hand calculation, write a 50+ character comparison and confirm self-review.',true);state.done.lab=true;persist();feedback('feedback-lab','Lab evidence saved. Your prose is self-reviewed; numerical evidence is bound to the latest run.');}
if(action==='csv'){if(!state.runs.length)return feedback('feedback-lab','Run a comparison first.',true);download('qf-chapter-06-all-runs.csv','run,input,month,value1,value2,detail\n'+state.runs.flatMap((run,i)=>run.rows.map((r,j)=>[i+1,run.parameter,j,r.wealth??r.mix,r.peak??r.buyHold,r.drawdown??r.weightA].join(','))).join('\n'),'text/csv');}
if(action==='grade'){const answers=Object.fromEntries(ASSESSMENTS.map(q=>[q.id,value('quiz-'+q.id)]));if(ASSESSMENTS.some(q=>answers[q.id].trim()===''))return feedback('feedback-assessment','Answer all eight questions before checking. No time limit applies.',true);const result=grade(answers);state.attempts.push({...result,answers,time:new Date().toISOString()});state.fields.quizDirty='';state.fields.revision='';delete state.done.assessment;persist();render(false);showAssessmentReview($('#feedback-assessment'),ASSESSMENTS,answers,result,check);}
if(action==='revision'){const a=state.attempts.at(-1);if(!a||!ASSESSMENTS.every(q=>a.answers[q.id]===value('quiz-'+q.id)))return feedback('feedback-revision','Submit your current answers before saving their feedback response.',true);if(value('revision').trim().length<30)return feedback('feedback-revision','Describe a specific correction or verification (at least 30 characters).',true);a.revision=value('revision');state.fields.quizDirty='';if(a.passed)state.done.assessment=true;persist();feedback('feedback-revision',a.passed?'Feedback response saved. Independent check complete.':'Response saved. Revise answers and resubmit to meet the criteria.');}
if(action==='card'){if(!['cardMethod','cardCheck','cardLimit'].every(id=>value(id).trim().length>=30)||value('cardCriteria')!=='yes')return feedback('feedback-finish','Complete all three 30+ character fields and confirm your self-review.',true);state.done.finish=true;persist();render(false);feedback('feedback-finish',STEPS.every(([id])=>state.done[id])?'Chapter complete. Export your evidence and card for your records.':'Portfolio comparison card saved. Use the checklist to complete any missing evidence.');}
});
$('#chapter-select').addEventListener('change',e=>{location.href=e.target.value==='1'?'../index.html':`../chapter-${e.target.value.padStart(2,'0')}/`;});$('#privacy-button').onclick=()=>$('#privacy-dialog').showModal();$('#close-privacy').onclick=()=>$('#privacy-dialog').close();$('#reset-progress').onclick=()=>{if(!confirm('Delete only Chapter 6 browser progress and runs? Other chapters and downloaded files remain.'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();location.hash='start';render();$('#announcement').textContent='Chapter 6 reset.';};window.addEventListener('hashchange',()=>render());render(false);
